                return str(k)
        return str(n - 1)

import math

class Solution:
    def smallestGoodBase(self, n: str) -> str:
        num = int(n)
        max_len = int(math.log(num,2))
        for l in range(max_len, 1, -1):
            b = int(num ** (l**-1))
            if (b**(l+1)-1) // (b-1) == num:
                return str(b)
        return str(num-1)

